<?php defined('ABSPATH')||exit;get_header();while(have_posts()):the_post();$id=get_the_ID();$terms=get_the_terms($id,'bakery_product_category');$allergens=get_the_terms($id,'bakery_allergen');$price=morgenbrot_product_price($id);$gallery=array_filter(array_map('absint',explode(',',(string)morgenbrot_meta($id,'gallery_ids'))));$images=array_unique(array_filter(array_merge(has_post_thumbnail()?array(get_post_thumbnail_id()):array(),$gallery)));$status=morgenbrot_meta($id,'availability_status')?:'in_stock';?><main id="main-content"><article class="section shell product-single"><div class="single-grid"><div class="product-gallery" data-gallery><?php if($images):?><div class="gallery-main"><?php echo wp_get_attachment_image($images[0],'large',false,array('alt'=>get_the_title(),'data-gallery-main'=>''));?></div><?php if(count($images)>1):?><div class="gallery-thumbs" aria-label="Produktgalerie"><?php foreach($images as$index=>$image_id):?><button type="button" data-gallery-thumb data-src="<?php echo esc_url(wp_get_attachment_image_url($image_id,'large'));?>" aria-label="Bild <?php echo esc_attr($index+1);?> anzeigen"><?php echo wp_get_attachment_image($image_id,'thumbnail',false,array('alt'=>''));?></button><?php endforeach;?></div><?php endif;?><?php else:morgenbrot_placeholder('bread');endif;?></div><div><p class="eyebrow"><?php echo esc_html($terms&&!is_wp_error($terms)?$terms[0]->name:'Backware');?></p><h1><?php the_title();?></h1><p class="sku">Artikelnummer: <?php echo esc_html(morgenbrot_meta($id,'sku')?:'—');?></p><p class="lead"><?php echo esc_html(get_the_excerpt());?></p><p class="price"><?php if($price['sale']):?><del><?php echo esc_html(morgenbrot_format_price($price['regular']));?></del> <strong><?php echo esc_html(morgenbrot_format_price($price['sale']));?></strong><?php else:echo esc_html(morgenbrot_format_price($price['regular']));endif;?> <small><?php echo esc_html(morgenbrot_meta($id,'price_unit'));?></small></p><p class="availability <?php echo esc_attr($status);?>"><?php echo esc_html(morgenbrot_availability_label($id));?><?php $stock=morgenbrot_meta($id,'stock_quantity');if(''!==$stock)echo' · '.esc_html($stock).' Stück';?></p><div class="badges"><?php foreach(['vegan'=>'Vegan','vegetarian'=>'Vegetarisch','seasonal'=>'Saisonal']as$k=>$v)if(morgenbrot_meta($id,$k))echo'<span>'.esc_html($v).'</span>';?></div><div class="entry-content"><?php the_content();?></div><dl class="facts"><dt>Gewicht</dt><dd><?php echo esc_html(morgenbrot_meta($id,'weight'));?></dd><dt>Zutaten</dt><dd><?php echo esc_html(morgenbrot_meta($id,'ingredients'));?></dd><dt>Allergene</dt><dd><?php echo esc_html($allergens&&!is_wp_error($allergens)?implode(', ',wp_list_pluck($allergens,'name')):'Keine Angaben');?></dd><dt>Hinweis</dt><dd><?php echo esc_html(morgenbrot_meta($id,'availability'));?></dd></dl><p class="allergen-note">Trotz sorgfältiger Herstellung können Spuren weiterer Allergene nicht vollständig ausgeschlossen werden.</p><?php if('out_of_stock'!==$status):?><form class="inline-order" method="get" action="<?php echo esc_url(home_url('/vorbestellen/'));?>"><input type="hidden" name="product" value="<?php echo esc_attr($id);?>"><label>Menge<input type="number" name="qty" min="1" max="50" value="1"></label><button class="button" type="submit">Zur Vorbestellung</button></form><?php endif;?></div></div></article><?php $related=new WP_Query(['post_type'=>'bakery_product','posts_per_page'=>3,'post__not_in'=>[$id],'tax_query'=>$terms&&!is_wp_error($terms)?[['taxonomy'=>'bakery_product_category','field'=>'term_id','terms'=>wp_list_pluck($terms,'term_id')]]:[]]);if($related->have_posts()):?><section class="section shell"><h2>Dazu passt</h2><div class="card-grid products"><?php while($related->have_posts()):$related->the_post();get_template_part('template-parts/product','card');endwhile;?></div></section><?php wp_reset_postdata();endif;?></main><?php endwhile;get_footer();
